import {createGame,step,act} from './engine.js';
import {render} from './render.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const canvas=$('#game'),ctx=canvas.getContext('2d',{alpha:false}),shell=$('#game-shell'),overlay=$('#overlay');
const game=createGame(),input={left:false,right:false};
let camera=0,lastTime=0,lastStatus='',lastHud=0,audio=null,sound=false,helpPaused=false,winSaved=false;
let records={wins:0,best:null};try{records={...records,...JSON.parse(localStorage.getItem('spirit-gate-record')||'{}')}}catch{}
const formatTime=s=>`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`;
function showRecord(){if(records.wins)$('#record').textContent=`已通关 ${records.wins} 次 · 最快 ${formatTime(records.best)}`;}showRecord();
function tone(name){if(!sound)return;try{audio ||= new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const notes={jump:[330,.065,'sine'],dash:[160,.1,'triangle'],claw:[220,.05,'triangle'],metal:[650,.1,'triangle'],ice:[900,.15,'sine'],hit:[110,.06,'square'],hurt:[80,.15,'sawtooth'],shard:[880,.28,'sine'],checkpoint:[540,.4,'sine'],boss:[140,.35,'triangle'],win:[1046,.5,'sine']};const n=notes[name];if(!n)return;const o=audio.createOscillator(),v=audio.createGain();o.type=n[2];o.frequency.setValueAtTime(n[0],audio.currentTime);o.frequency.exponentialRampToValueAtTime(n[0]*(name==='hurt'?.4:1.35),audio.currentTime+n[1]);v.gain.setValueAtTime(.025,audio.currentTime);v.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+n[1]);o.connect(v);v.connect(audio.destination);o.start();o.stop(audio.currentTime+n[1]);}catch{}}
function perform(action){if(action==='restart'){winSaved=false;camera=0;input.left=input.right=false;}const n=game.events.length;act(game,action);game.events.slice(n).forEach(tone);syncStatus();if(!$('#help-dialog').open)canvas.focus({preventScroll:true});}
const startHTML=overlay.innerHTML;
function syncStatus(){if(lastStatus===game.status)return;lastStatus=game.status;shell.dataset.status=game.status;overlay.classList.toggle('hidden',game.status==='playing');$('#pause-button').textContent=game.status==='paused'?'▶':'Ⅱ';$('#pause-button').setAttribute('aria-label',game.status==='paused'?'继续游戏':'暂停游戏');
 const stats=`<div class="end-stats"><span><strong>${game.shards} / 3</strong>灵印</span><span><strong>${game.kills}</strong>击退灵影</span><span><strong>${formatTime(game.time)}</strong>探索用时</span></div>`;
 if(game.status==='ready'){overlay.innerHTML=startHTML;}
 if(game.status==='paused')overlay.innerHTML='<div class="end-content"><span class="end-symbol">☾</span><p class="eyebrow">TAKE A BREATH</p><h2>在林间，歇一会。</h2><p>灵境会等你。准备好后，继续这段旅程。</p><div class="end-buttons"><button class="primary-button" data-action="pause">继续探索 <span>→</span></button><button class="secondary-button" data-open-help>操作指南</button></div></div>';
 if(game.status==='dead')overlay.innerHTML=`<div class="end-content"><span class="end-symbol">❋</span><p class="eyebrow">ANOTHER BEGINNING</p><h2>每次归来，都更靠近。</h2><p>${game.checkpointTaken?'从林间灵泉重新出发。':'从森林入口重新出发。'}已收集的灵印会保留。</p>${stats}<div class="end-buttons"><button class="primary-button" data-action="respawn">重新凝聚 <span>→</span></button><button class="secondary-button" data-action="restart">全新试炼</button></div></div>`;
 if(game.status==='won'){if(!winSaved){records.wins++;records.best=records.best===null?game.time:Math.min(records.best,game.time);try{localStorage.setItem('spirit-gate-record',JSON.stringify(records))}catch{}winSaved=true;showRecord();}overlay.innerHTML=`<div class="end-content"><span class="end-symbol">✧</span><p class="eyebrow">TRIAL COMPLETE</p><h2>门的另一边，是新的开始。</h2><p>三枚灵印已经归位。你完成了第一次森林试炼。</p>${stats}<div class="end-buttons"><button class="primary-button" data-action="restart">再赴灵境 <span>↻</span></button></div></div>`;}
}
function openHelp(){helpPaused=game.status==='playing';if(helpPaused){act(game,'pause');syncStatus()}input.left=input.right=false;$('#help-dialog').showModal();}
function closeHelp(){$('#help-dialog').close();if(helpPaused&&game.status==='paused')perform('pause');helpPaused=false;}
$('#help-button').addEventListener('click',openHelp);$('#close-help').addEventListener('click',closeHelp);$('#help-done').addEventListener('click',closeHelp);$('#help-dialog').addEventListener('cancel',e=>{e.preventDefault();closeHelp()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.closest('.touch-controls'))perform(b.dataset.action);if(e.target.closest('#start-button'))perform('start');if(e.target.closest('[data-open-help]'))openHelp();});
$('#pause-button').addEventListener('click',()=>perform('pause'));
$('#restart-button').addEventListener('click',()=>perform('restart'));
$('#sound-button').addEventListener('click',()=>{sound=!sound;$('#sound-button span').textContent=sound?'音效开':'音效关';$('#sound-button').setAttribute('aria-label',sound?'关闭音效':'打开音效');if(sound)tone('shard')});
$('#fullscreen-button').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(shell.requestFullscreen)await shell.requestFullscreen();else{game.message='此浏览器暂不支持全屏，可横屏游玩。';game.messageUntil=game.time+4;}}catch{game.message='当前环境无法全屏，可直接在页面中游玩。';game.messageUntil=game.time+4;}});
const actionKeys={Space:'jump',KeyW:'jump',ArrowUp:'jump',KeyJ:'claw',KeyK:'metal',KeyL:'ice',ShiftLeft:'dash',ShiftRight:'dash'};
window.addEventListener('keydown',e=>{if($('#help-dialog').open)return;const key=e.code;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Space','Tab'].includes(key)&&key!=='Tab')e.preventDefault();if(key==='KeyA'||key==='ArrowLeft')input.left=true;if(key==='KeyD'||key==='ArrowRight')input.right=true;if(e.repeat)return;if(key==='Escape'||key==='KeyP')perform('pause');if(key==='Enter'){if(game.status==='ready')perform('start');else if(game.status==='dead')perform('respawn');else if(game.status==='won')perform('restart');else if(game.status==='paused')perform('pause');}if(actionKeys[key])perform(actionKeys[key]);});
window.addEventListener('keyup',e=>{if(e.code==='KeyA'||e.code==='ArrowLeft')input.left=false;if(e.code==='KeyD'||e.code==='ArrowRight')input.right=false;});
function loseFocus(){input.left=input.right=false;if(game.status==='playing')perform('pause');}
window.addEventListener('blur',loseFocus);document.addEventListener('visibilitychange',()=>{if(document.hidden)loseFocus()});
$$('.touch-controls button').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);if(b.dataset.hold)input[b.dataset.hold]=true;else perform(b.dataset.action)});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>{if(b.dataset.hold)input[b.dataset.hold]=false});});
function updateHUD(){const p=game.player;$('#health-bar').style.width=`${p.hp/p.maxHp*100}%`;$('#energy-bar').style.width=`${p.energy/p.maxEnergy*100}%`;$('#hp-label').textContent=`${Math.ceil(p.hp)} / ${p.maxHp}`;$('#shard-count').textContent=game.shards;
const zone=p.x<900?0:p.x<1690?1:p.x<2930?2:3;$('#zone-label').innerHTML=`0${zone+1} <span>${['出生之林','镜水溪','古树庭','灵境之门'][zone]}</span>`;$$('.route-stop').forEach((n,i)=>n.classList.toggle('active',i<=zone));$('#route-fill').style.width=`${Math.min(100,Math.max(0,(p.x-110)/3280*100))}%`;
$('#journey-text').textContent=game.shards<3?`灵印 ${game.shards}/3 · 留意树冠的微光`:game.bossDefeated?'灵门已开启 · 向右前行':'灵印已集齐 · 挑战守门者';$('#game-status').innerHTML=`<i></i>${({ready:'灵境等待开启',playing:'探索中',paused:'已暂停',dead:'等待重新凝聚',won:'森林试炼完成'})[game.status]}${game.status==='ready'?'':` &nbsp; / &nbsp; ${formatTime(game.time)}`}`;
$$('[data-cd]').forEach(n=>{const cd=game.cooldowns[n.dataset.cd]||0;n.style.display=cd>.05?'flex':'none';n.textContent=cd.toFixed(1)});const toast=$('#toast');toast.classList.toggle('visible',game.status==='playing'&&game.time<game.messageUntil);toast.textContent=game.message;}
function frame(now){const dt=lastTime?Math.min((now-lastTime)/1000,.05):1/60;lastTime=now;step(game,input,dt);game.events.forEach(tone);const target=Math.max(0,Math.min(game.width-960,game.player.x-350));camera+=(target-camera)*Math.min(1,dt*6);render(ctx,game,{camera,width:960,height:540});syncStatus();if(now-lastHud>65){updateHUD();lastHud=now;}requestAnimationFrame(frame);}
syncStatus();updateHUD();requestAnimationFrame(frame);
